exercises.solution:
def sum_with_helper(nums):
    total = 0
    def add(x):
        nonlocal total
        total += x
    for n in nums:
        add(n)
    return total

def make_accumulator(start=0):
    total = start
    def add(x=0, reset=False):
        nonlocal total
        if reset:
            total = start
        else:
            total += x
        return total
    return add

